// MIN COST CLIMBING STAIRS (#746)
// O(n) time, O(n) space -> O(1) space with rolling variables

// FULL DP TABLE (for understanding):
function minCostClimbingStairs_table(cost) {
    const n = cost.length;
    const dp = new Array(n + 1).fill(0);
    // dp[0] = dp[1] = 0: start for free at step 0 or 1
    for (let i = 2; i <= n; i++) {
        dp[i] = Math.min(
            dp[i-1] + cost[i-1], // arrive from step i-1, paid cost[i-1]
            dp[i-2] + cost[i-2]  // arrive from step i-2, paid cost[i-2]
        );
    }
    return dp[n]; // top = step n, beyond the last stair
}

// TRACE on cost=[10,15,20]:
// dp[0]=0, dp[1]=0
// dp[2]=min(dp[1]+cost[1], dp[0]+cost[0])=min(0+15, 0+10)=10
// dp[3]=min(dp[2]+cost[2], dp[1]+cost[1])=min(10+20, 0+15)=15
// Answer: 15 (path: start at step 0, pay 10, jump to step 2, pay 20... wait)
// Let's verify: start at step 1 (free), pay cost[1]=15, jump to top. Total=15. ✓
// Alternative: start at step 0 (free), pay 10, jump to step 2, pay 20, jump to top. Total=30. ✗
// Alternative: start at step 0, pay 10, jump to step 1... wait, step 1 costs 15... Total=25. ✗
// So best is: start step 1, pay 15. Answer=15. ✓

// SPACE OPTIMISED — O(1)
function minCostClimbingStairs(cost) {
    const n = cost.length;
    let prev2 = 0, prev1 = 0; // dp[0] and dp[1]
    for (let i = 2; i <= n; i++) {
        const curr = Math.min(prev1 + cost[i-1], prev2 + cost[i-2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1; // dp[n]
}

console.log(minCostClimbingStairs([10,15,20]));      // 15
console.log(minCostClimbingStairs([1,100,1,1,1,100,1,1,100,1])); // 6

// COMMON BUG: using dp[n-1] instead of dp[n] as the answer
// The top of the staircase is BEYOND the last step
// dp[n-1] would be the cost to reach the last step, not the top
// Always target dp[n] for this problem

