// DECODE WAYS (#91) — O(n) time, O(n) space -> O(1) space

// FULL DP TABLE (for understanding transitions):
function numDecodings_table(s) {
    if (!s || s[0] === '0') return 0; // leading zero: impossible
    const n = s.length;
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1; // empty prefix: 1 way
    dp[1] = 1; // first char (confirmed non-zero above): 1 way

    for (let i = 2; i <= n; i++) {
        // Single-digit decode: s[i-1] must be '1'-'9'
        if (s[i-1] !== '0') {
            dp[i] += dp[i-1];
        }
        // Two-digit decode: s[i-2..i-1] must be '10'-'26'
        const twoDigit = parseInt(s.substring(i-2, i));
        if (twoDigit >= 10 && twoDigit <= 26) {
            dp[i] += dp[i-2];
        }
    }
    return dp[n];
}

// TRACE on s='226':
// dp=[1,1,?,?]
// i=2: s[1]='2'!='0' -> dp[2]+=dp[1]=1. twoDigit='22'=22, 10<=22<=26 -> dp[2]+=dp[0]=1. dp[2]=2
// i=3: s[2]='6'!='0' -> dp[3]+=dp[2]=2. twoDigit='26'=26, 10<=26<=26 -> dp[3]+=dp[1]=1. dp[3]=3
// Answer: 3 ways: (2,2,6) -> (B,B,F), (22,6) -> (V,F), (2,26) -> (B,Z)

// TRACE on s='06': s[0]='0' -> return 0 immediately
// TRACE on s='10':
// dp=[1,1,?,?]
// i=2: s[1]='0'=='0' -> skip single. twoDigit='10'=10 -> dp[2]+=dp[0]=1. dp[2]=1
// Answer: 1 way: (10) -> (J)

// SPACE OPTIMISED — O(1)
function numDecodings(s) {
    if (!s || s[0] === '0') return 0;
    let prev2 = 1; // dp[i-2], starts as dp[0]=1
    let prev1 = 1; // dp[i-1], starts as dp[1]=1

    for (let i = 2; i <= s.length; i++) {
        let curr = 0;
        if (s[i-1] !== '0') curr += prev1;
        const two = parseInt(s.substring(i-2, i));
        if (two >= 10 && two <= 26) curr += prev2;
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

console.log(numDecodings('226'));  // 3
console.log(numDecodings('06'));   // 0
console.log(numDecodings('10'));   // 1
console.log(numDecodings('2101')); // 1  (only: 2,10,1 -> B,J,A)
console.log(numDecodings('11106')); // 2

