// WORD BREAK (#139) — O(n^2) time, O(n + dict_size) space
function wordBreak(s, wordDict) {
    const wordSet = new Set(wordDict); // O(1) lookup
    const n = s.length;
    const dp = new Array(n + 1).fill(false);
    dp[0] = true; // empty string: always segmentable

    for (let i = 1; i <= n; i++) {
        for (let j = 0; j < i; j++) {
            // If prefix s[0..j-1] is segmentable AND s[j..i-1] is a word
            if (dp[j] && wordSet.has(s.substring(j, i))) {
                dp[i] = true;
                break; // found a valid segmentation up to i, move on
            }
        }
    }
    return dp[n];
}

// TRACE on s='leetcode', dict=['leet','code']:
// dp[0]=true
// i=1: j=0: dp[0]=T, s[0..0]='l' not in dict. dp[1]=false
// i=2: j=0: 'le' not. j=1: dp[1]=F. dp[2]=false
// i=3: j=0: 'lee' not. j=1: F. j=2: F. dp[3]=false
// i=4: j=0: dp[0]=T, s[0..3]='leet' IN DICT -> dp[4]=true, break
// i=5..7: similar, dp[5]=dp[6]=dp[7]=false
// i=8: j=4: dp[4]=T, s[4..7]='code' IN DICT -> dp[8]=true
// Answer: true

console.log(wordBreak('leetcode', ['leet','code']));    // true
console.log(wordBreak('applepenapple', ['apple','pen'])); // true
console.log(wordBreak('catsandog', ['cats','dog','sand','and','cat'])); // false

// WORD BREAK II (#140) — return all valid segmentations
// Backtracking with memoisation: O(n * 2^n) worst case
function wordBreakII(s, wordDict) {
    const wordSet = new Set(wordDict);
    const memo = new Map();

    function dfs(start) {
        if (start === s.length) return [''];
        if (memo.has(start)) return memo.get(start);

        const result = [];
        for (let end = start + 1; end <= s.length; end++) {
            const word = s.substring(start, end);
            if (wordSet.has(word)) {
                const rest = dfs(end);
                for (const r of rest) {
                    result.push(word + (r ? ' ' + r : ''));
                }
            }
        }
        memo.set(start, result);
        return result;
    }
    return dfs(0);
}

