// UNIQUE PATHS (#62) — O(m*n) time, O(m*n) space
function uniquePaths_2D(m, n) {
    // dp[r][c] = paths to reach (r,c)
    const dp = Array.from({length: m}, () => new Array(n).fill(1));
    // Fill with 1 handles base cases: first row and first column are all 1

    for (let r = 1; r < m; r++) {
        for (let c = 1; c < n; c++) {
            dp[r][c] = dp[r-1][c] + dp[r][c-1];
        }
    }
    return dp[m-1][n-1];
}

// SPACE OPTIMISED — O(n) single row
function uniquePaths(m, n) {
    const dp = new Array(n).fill(1); // initialise as first row: all 1s
    for (let r = 1; r < m; r++) {
        for (let c = 1; c < n; c++) {
            // dp[c] (old value) = paths from row above
            // dp[c-1] (just updated) = paths from left
            dp[c] += dp[c-1];
        }
        // After each row: dp[0] stays 1 (first column always 1)
    }
    return dp[n-1];
}

console.log(uniquePaths(3, 7)); // 28
console.log(uniquePaths(3, 2)); // 3

// UNIQUE PATHS II (#63) — with obstacles
function uniquePathsWithObstacles(obstacleGrid) {
    const m = obstacleGrid.length, n = obstacleGrid[0].length;
    if (obstacleGrid[0][0] === 1 || obstacleGrid[m-1][n-1] === 1) return 0;

    const dp = new Array(n).fill(0);
    dp[0] = 1; // start cell

    // First row: stop at first obstacle
    for (let c = 0; c < n; c++) {
        if (obstacleGrid[0][c] === 1) dp[c] = 0;
        else if (c > 0) dp[c] = dp[c-1];
    }

    for (let r = 1; r < m; r++) {
        // Reset first column if obstacle
        if (obstacleGrid[r][0] === 1) dp[0] = 0;
        for (let c = 1; c < n; c++) {
            if (obstacleGrid[r][c] === 1) dp[c] = 0;
            else dp[c] += dp[c-1];
        }
    }
    return dp[n-1];
}

console.log(uniquePathsWithObstacles([[0,0,0],[0,1,0],[0,0,0]])); // 2

// MATHEMATICAL FORMULA (for insight)
// Total moves = (m-1) downs + (n-1) rights = m+n-2 moves
// Choose which (m-1) moves are downs: C(m+n-2, m-1)
function uniquePaths_math(m, n) {
    // C(m+n-2, m-1) = (m+n-2)! / ((m-1)! * (n-1)!)
    let result = 1;
    for (let i = 0; i < m-1; i++) {
        result = result * (n + i) / (i + 1);
    }
    return Math.round(result);
}

