// LONGEST COMMON SUBSEQUENCE (#1143) — O(m*n) time, O(m*n) space
function longestCommonSubsequence(text1, text2) {
    const m = text1.length, n = text2.length;
    // dp[i][j] = LCS length of text1[0..i-1] and text2[0..j-1]
    const dp = Array.from({length: m+1}, () => new Array(n+1).fill(0));
    // Base cases: row 0 and col 0 are all 0 (already initialised)

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (text1[i-1] === text2[j-1]) {
                dp[i][j] = 1 + dp[i-1][j-1]; // characters match: extend
            } else {
                dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]); // skip one
            }
        }
    }
    return dp[m][n];
}

// TRACE on text1='abcde', text2='ace':
//     "" a  c  e
// "" [ 0, 0, 0, 0]
// a  [ 0, 1, 1, 1]  dp[1][1]: 'a'=='a' -> 1+dp[0][0]=1
// b  [ 0, 1, 1, 1]  dp[2][1]: 'b'!='a' -> max(dp[1][1],dp[2][0])=1
// c  [ 0, 1, 2, 2]  dp[3][2]: 'c'=='c' -> 1+dp[2][1]=2
// d  [ 0, 1, 2, 2]
// e  [ 0, 1, 2, 3]  dp[5][3]: 'e'=='e' -> 1+dp[4][2]=3
// Answer: 3 ('ace')

console.log(longestCommonSubsequence('abcde', 'ace'));  // 3
console.log(longestCommonSubsequence('abc', 'abc'));    // 3
console.log(longestCommonSubsequence('abc', 'def'));    // 0

// SPACE OPTIMISED — O(n) using two rows
function lcsOptimised(text1, text2) {
    const m = text1.length, n = text2.length;
    let prev = new Array(n+1).fill(0);
    let curr = new Array(n+1).fill(0);

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (text1[i-1] === text2[j-1]) {
                curr[j] = 1 + prev[j-1]; // diagonal
            } else {
                curr[j] = Math.max(prev[j], curr[j-1]); // above or left
            }
        }
        [prev, curr] = [curr, new Array(n+1).fill(0)]; // swap rows
    }
    return prev[n];
}

// RECONSTRUCT the actual LCS string (not just length)
function reconstructLCS(text1, text2, dp) {
    let i = text1.length, j = text2.length;
    const result = [];
    while (i > 0 && j > 0) {
        if (text1[i-1] === text2[j-1]) {
            result.push(text1[i-1]); i--; j--; // match: include
        } else if (dp[i-1][j] > dp[i][j-1]) {
            i--; // came from above
        } else {
            j--; // came from left
        }
    }
    return result.reverse().join('');
}

